SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, COUNT(CASE WHEN a.admittime <= 72 THEN 1 END)::FLOAT / NULLIF(COUNT(CASE WHEN a.admittime > 72 THEN 1 END), 0) AS ratio FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.subject_id = 757071 AND p.gender = 'M' AND p.anchor_age BETWEEN 66 AND 76 AND d.icd_code IN ('440.0', '440.1') GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version ORDER BY ratio DESC NULLS LAST;